import React, { useState, useEffect } from "react";
import ChartistGraph from "react-chartist";
import {
  Card,
  Container,
  Row,
  Col,
  Form,
  Button,
} from "react-bootstrap";
import "chartist/dist/chartist.min.css";

/* ===============================
   STYLE (ใช้ logic เดียวกับ Dashboard)
================================ */
const themeStyle = `
  .chart-scroll {
    overflow-x: auto;
    overflow-y: hidden;
  }
`;

function History() {
  /* ===============================
     STATE
  ================================ */
  const currentYearCE = new Date().getFullYear();

  const [selectedDay, setSelectedDay] = useState(new Date().getDate().toString());
  const [selectedMonth, setSelectedMonth] = useState(
    (new Date().getMonth() + 1).toString().padStart(2, "0")
  );
  const [selectedYearBE, setSelectedYearBE] = useState(
    (currentYearCE + 543).toString()
  );

  const [startTime, setStartTime] = useState("07:00");
  const [endTime, setEndTime] = useState("22:00");
  const [cameraId, setCameraId] = useState("CAM01");

  // ⭐ เหมือน Dashboard → series เดียว
  const [chartState, setChartState] = useState({
    labels: [],
    series: [[],[],[],[]]
  });

  const [loading, setLoading] = useState(false);

  /* ===============================
     DATE OPTIONS
  ================================ */
  const monthsThai = [
    { val: "01", name: "มกราคม" }, { val: "02", name: "กุมภาพันธ์" },
    { val: "03", name: "มีนาคม" }, { val: "04", name: "เมษายน" },
    { val: "05", name: "พฤษภาคม" }, { val: "06", name: "มิถุนายน" },
    { val: "07", name: "กรกฎาคม" }, { val: "08", name: "สิงหาคม" },
    { val: "09", name: "กันยายน" }, { val: "10", name: "ตุลาคม" },
    { val: "11", name: "พฤศจิกายน" }, { val: "12", name: "ธันวาคม" }
  ];

  const yearsBE = [currentYearCE + 542, currentYearCE + 543, currentYearCE + 544];

  const daysCount = new Date(
    parseInt(selectedYearBE) - 543,
    parseInt(selectedMonth),
    0
  ).getDate();

  const daysArray = Array.from({ length: daysCount }, (_, i) =>
    (i + 1).toString()
  );

  const timeOptions = [];
  for (let h = 7; h <= 22; h++) {
    timeOptions.push(`${h.toString().padStart(2, "0")}:00`);
  }

  useEffect(() => {
    if (parseInt(selectedDay) > daysCount) {
      setSelectedDay(daysCount.toString());
    }
  }, [selectedMonth, selectedYearBE, daysCount, selectedDay]);

  /* ===============================
     FETCH DATA
  ================================ */
  const handleSearch = async () => {
    setLoading(true);

    const yearCE = parseInt(selectedYearBE) - 543;
    const formattedDate = `${yearCE}-${selectedMonth}-${selectedDay.padStart(2, "0")}`;

    try {
      const res = await fetch(
        `http://localhost:3000/api/history?cameraId=${cameraId}&date=${formattedDate}&startTime=${startTime}&endTime=${endTime}`
      );
      const result = await res.json();

      console.log("RAW RESULT:", result);

      if (!result || !result.labels || !result.series) {
        alert("ข้อมูลจาก backend ไม่ถูกต้อง");
        return;
      }

      // ⭐ รองรับทั้ง series = [] และ series = [[]]
      const rawSeries = Array.isArray(result.series[0])
        ? result.series[0]
        : result.series;

      const cleanSeries = rawSeries.map(v =>
        v === null || v === undefined || isNaN(Number(v))
          ? 0
          : Number(v)
      );

      // ⭐ ป้องกัน labels กับ series ยาวไม่เท่ากัน
      const minLen = Math.min(result.labels.length, cleanSeries.length);

      setChartState({
        labels: result.labels.slice(0, minLen),
        series: [cleanSeries.slice(0, minLen)]
      });

    } catch (err) {
      console.error(err);
      alert("เชื่อมต่อ Server ไม่ได้");
    } finally {
      setLoading(false);
    }
  };


  /* ===============================
     CHART CONFIG (เหมือน Dashboard)
  ================================ */
  const barChartData = {
    labels: chartState.labels,
    series: chartState.series
  };

  const barChartOptions = {
    height: "400px",
    axisX: { showGrid: false, offset: 60 },
    axisY: {
      onlyInteger: true,
      low: 0,
      high: Math.max(...(chartState.series[0] || [0])) + 5
    },
    chartPadding: {
      left: 20,
      right: 20,
      top: 40,
      bottom: 40
    },
    fullWidth: true
  };

  // ⭐ copy จาก Dashboard ตรง ๆ
  const drawBarLabels = (data) => {
    if (data.type === "bar") {
      const color = data.value.y > 20 ? "#dc3545" : "#198754";

      data.element.attr({
        style: `stroke: ${color}; stroke-width: 30px;`
      });

      data.group.elem("text", {
        x: data.x2,
        y: data.y2 - 15,
        style: "font-size:14px;fill:#000;font-weight:bold;text-anchor:middle",
      }).text(data.value.y);
    }
  };

  /* ===============================
     RENDER
  ================================ */
  return (
    <Container fluid>
      <style>{themeStyle}</style>

      <Row>
        <Col md="12">
          <Card>
            <Card.Header>
              <Card.Title as="h4">ค้นหาข้อมูลย้อนหลัง</Card.Title>
            </Card.Header>

            <Card.Body>
              <Row className="align-items-end g-3">

                {/* สถานี */}
                <Col lg="2" md="4">
                  <Form.Group>
                    <Form.Label>สถานี</Form.Label>
                    <Form.Select value={cameraId} onChange={e => setCameraId(e.target.value)}>
                      <option value="CAM01">วิศวะ</option>
                      <option value="CAM02">วิทยาศาสตร์</option>
                      <option value="CAM03">ศิลปศาสตร์</option>
                      <option value="CAM04">PKY</option>
                    </Form.Select>
                  </Form.Group>
                </Col>

                {/* วันที่ */}
                <Col lg="4" md="8">
                  <Form.Label>วันที่ (พ.ศ.)</Form.Label>
                  <div className="d-flex gap-2">
                    <Form.Select value={selectedDay} onChange={e => setSelectedDay(e.target.value)}>
                      {daysArray.map(d => <option key={d}>{d}</option>)}
                    </Form.Select>
                    <Form.Select value={selectedMonth} onChange={e => setSelectedMonth(e.target.value)}>
                      {monthsThai.map(m => (
                        <option key={m.val} value={m.val}>{m.name}</option>
                      ))}
                    </Form.Select>
                    <Form.Select value={selectedYearBE} onChange={e => setSelectedYearBE(e.target.value)}>
                      {yearsBE.map(y => <option key={y}>{y}</option>)}
                    </Form.Select>
                  </div>
                </Col>

                {/* เวลา */}
                <Col lg="4" md="8">
                  <Form.Label>ช่วงเวลา</Form.Label>
                  <div className="d-flex gap-2">
                    <Form.Select value={startTime} onChange={e => setStartTime(e.target.value)}>
                      {timeOptions.map(t => <option key={t}>{t}</option>)}
                    </Form.Select>
                    <Form.Select value={endTime} onChange={e => setEndTime(e.target.value)}>
                      {timeOptions.map(t => <option key={t}>{t}</option>)}
                    </Form.Select>
                  </div>
                </Col>

                {/* ปุ่มค้นหา */}
                <Col lg="2" md="4">
                  <Button
                    className="w-100"
                    variant="primary"
                    onClick={handleSearch}
                    disabled={loading}
                  >
                    {loading ? "กำลังโหลด..." : "ค้นหา"}
                  </Button>
                </Col>

              </Row>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {barChartData.series[0].length > 0 && (
        <Row className="mt-4">
          <Col md="12">
            <Card>
              <Card.Header>
                <Card.Title as="h5">
                  กราฟย้อนหลัง : {cameraId}
                </Card.Title>
              </Card.Header>

              <Card.Body>
                <div className="chart-scroll">
                  <div
                    style={{
                      width: Math.max(chartState.labels.length * 70, 600),
                      height: "400px"
                    }}
                  >
                    <ChartistGraph
                      data={barChartData}
                      type="Bar"
                      options={barChartOptions}
                      listener={{ draw: drawBarLabels }}
                    />
                  </div>
                </div>
              </Card.Body>
            </Card>
          </Col>
        </Row>
      )}
    </Container>
  );
}

export default History;
